import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalUpdateJSON,
  NodeKey,
  SerializedElementNode,
  Spread,
} from "lexical";
import { ElementNode } from "lexical";

export type SerializedLayoutContainerNode = Spread<
  {
    templateColumns: string;
  },
  SerializedElementNode
>;

const convertLayoutContainerElement = (
  domNode: HTMLElement
): DOMConversionOutput | null => {
  const templateColumns = domNode.style.gridTemplateColumns;
  if (!templateColumns) {
    return null;
  }

  return {
    node: $createLayoutContainerNode(templateColumns),
  };
};

export class LayoutContainerNode extends ElementNode {
  __templateColumns: string;

  constructor(templateColumns: string, key?: NodeKey) {
    super(key);
    this.__templateColumns = templateColumns;
  }

  static getType(): string {
    return "layout-container";
  }

  static clone(node: LayoutContainerNode): LayoutContainerNode {
    return new LayoutContainerNode(node.__templateColumns, node.__key);
  }

  static importDOM(): DOMConversionMap | null {
    return {
      div: (domNode: HTMLElement) => {
        if (!domNode.hasAttribute("data-lexical-layout-container")) {
          return null;
        }

        return {
          conversion: convertLayoutContainerElement,
          priority: 2,
        };
      },
    };
  }

  static importJSON(
    serializedNode: SerializedLayoutContainerNode
  ): LayoutContainerNode {
    return $createLayoutContainerNode().updateFromJSON(serializedNode);
  }

  createDOM(config: EditorConfig): HTMLElement {
    const dom = document.createElement("div");
    dom.setAttribute("data-lexical-layout-container", "true");
    dom.style.gridTemplateColumns = this.__templateColumns;

    if (typeof config.theme.layoutContainer === "string") {
      addClassNamesToElement(dom, config.theme.layoutContainer);
    }

    return dom;
  }

  updateDOM(prevNode: this, dom: HTMLElement): boolean {
    if (prevNode.__templateColumns !== this.__templateColumns) {
      dom.style.gridTemplateColumns = this.__templateColumns;
    }

    return false;
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement("div");
    element.setAttribute("data-lexical-layout-container", "true");
    element.style.gridTemplateColumns = this.__templateColumns;

    return { element };
  }

  exportJSON(): SerializedLayoutContainerNode {
    return {
      ...super.exportJSON(),
      templateColumns: this.__templateColumns,
      type: "layout-container",
      version: 1,
    };
  }

  updateFromJSON(
    serializedNode: LexicalUpdateJSON<SerializedLayoutContainerNode>
  ): this {
    return super
      .updateFromJSON(serializedNode)
      .setTemplateColumns(serializedNode.templateColumns);
  }

  getTemplateColumns(): string {
    return this.getLatest().__templateColumns;
  }

  setTemplateColumns(templateColumns: string): this {
    const self = this.getWritable();
    self.__templateColumns = templateColumns;
    return self;
  }

  isShadowRoot(): boolean {
    return true;
  }

  canBeEmpty(): boolean {
    return false;
  }
}

export function $createLayoutContainerNode(
  templateColumns = ""
): LayoutContainerNode {
  return new LayoutContainerNode(templateColumns);
}

import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  EditorConfig,
  LexicalNode,
  SerializedElementNode,
} from "lexical";
import { $isParagraphNode, ElementNode } from "lexical";

export type SerializedLayoutItemNode = SerializedElementNode;

const convertLayoutItemElement = (): DOMConversionOutput => {
  return {
    node: $createLayoutItemNode(),
  };
};

export function $isEmptyLayoutItemNode(node: LexicalNode): boolean {
  if (!$isLayoutItemNode(node) || node.getChildrenSize() !== 1) {
    return false;
  }

  const firstChild = node.getFirstChild();
  return $isParagraphNode(firstChild) && firstChild.isEmpty();
}

export class LayoutItemNode extends ElementNode {
  static getType(): string {
    return "layout-item";
  }

  static clone(node: LayoutItemNode): LayoutItemNode {
    return new LayoutItemNode(node.__key);
  }

  static importDOM(): DOMConversionMap | null {
    return {
      div: (domNode: HTMLElement) => {
        if (!domNode.hasAttribute("data-lexical-layout-item")) {
          return null;
        }

        return {
          conversion: convertLayoutItemElement,
          priority: 2,
        };
      },
    };
  }

  static importJSON(serializedNode: SerializedLayoutItemNode): LayoutItemNode {
    return $createLayoutItemNode().updateFromJSON(serializedNode);
  }

  createDOM(config: EditorConfig): HTMLElement {
    const dom = document.createElement("div");
    dom.setAttribute("data-lexical-layout-item", "true");

    if (typeof config.theme.layoutItem === "string") {
      addClassNamesToElement(dom, config.theme.layoutItem);
    }

    return dom;
  }

  updateDOM(): boolean {
    return false;
  }

  collapseAtStart(): boolean {
    const parent = this.getParentOrThrow();

    if (
      this.is(parent.getFirstChild()) &&
      parent.getChildren().every($isEmptyLayoutItemNode)
    ) {
      parent.remove();
      return true;
    }

    return false;
  }

  isShadowRoot(): boolean {
    return true;
  }
}

export function $createLayoutItemNode(): LayoutItemNode {
  return new LayoutItemNode();
}

export function $isLayoutItemNode(
  node: LexicalNode | null | undefined
): node is LayoutItemNode {
  return node instanceof LayoutItemNode;
}

import type { NodeKey } from "lexical";
import { createCommand } from "lexical";

export interface InsertLayoutPayload {
  /**
   * When omitted or empty the plugin opens its own preset dialog instead of
   * applying a layout directly — the slash menu and toolbars dispatch the
   * bare command without owning any dialog UI.
   */
  targetNodeKey?: NodeKey;
  templateColumns?: string;
}

export const INSERT_LAYOUT_COMMAND = createCommand<InsertLayoutPayload>(
  "INSERT_LAYOUT_COMMAND"
);

export interface LayoutPreset {
  description: string;
  label: string;
  value: string;
}

export const DEFAULT_LAYOUT_TEMPLATE = "1fr 1fr";

export const LAYOUT_PRESETS: LayoutPreset[] = [
  {
    description: "Two equal columns",
    label: "2 columns (equal width)",
    value: "1fr 1fr",
  },
  {
    description: "Sidebar plus content",
    label: "2 columns (25% - 75%)",
    value: "1fr 3fr",
  },
  {
    description: "Three equal columns",
    label: "3 columns (equal width)",
    value: "1fr 1fr 1fr",
  },
  {
    description: "Three balanced columns",
    label: "3 columns (25% - 50% - 25%)",
    value: "1fr 2fr 1fr",
  },
  {
    description: "Four equal columns",
    label: "4 columns (equal width)",
    value: "1fr 1fr 1fr 1fr",
  },
];

import { PanelsTopLeftIcon } from "lucide-react";
import { LayoutContainerNode } from "../../core/nodes/layout/container-node";
import { LayoutItemNode } from "../../core/nodes/layout/item-node";
import type { ExtraEditorFeature } from "../../core/types";
import { INSERT_LAYOUT_COMMAND } from "./commands";
import { LayoutPlugin } from "./plugin";

/**
 * Installs the layout feature: the container/item nodes, the column preset
 * picker and the shared insert-menu entry. Ships as the `editor-layouts`
 * registry item.
 */
export const layoutFeature: ExtraEditorFeature = {
  id: "layout",
  nodes: [LayoutContainerNode, LayoutItemNode],
  plugin: LayoutPlugin,
  slashCommands: [
    {
      command: {
        description: "Multi-column content layout",
        icon: PanelsTopLeftIcon,
        id: "columns",
        keywords: ["columns", "layout", "grid", "multi-column"],
        label: "Columns",
      },
      run: (editor) => {
        editor.dispatchCommand(INSERT_LAYOUT_COMMAND, {});
      },
    },
  ],
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  $getNodeByKey,
  $getSelection,
  $isElementNode,
  $isRangeSelection,
  $isTextNode,
  COMMAND_PRIORITY_EDITOR,
  COMMAND_PRIORITY_HIGH,
} from "lexical";
import { useEffect, useState } from "react";
import { INSERT_LAYOUT_COMMAND } from "./commands";
import { LayoutPresetDialog } from "./preset-dialog";
import { applyLayoutPreset } from "./utils";

const EMPTY_DIALOG_STATE = {
  open: false,
  pendingTargetKey: null as string | null,
};

export function LayoutPlugin() {
  const [editor] = useLexicalComposerContext();
  const [dialogState, setDialogState] = useState(EMPTY_DIALOG_STATE);

  useEffect(() => {
    return editor.registerCommand(
      INSERT_LAYOUT_COMMAND,
      ({ targetNodeKey, templateColumns }) => {
        if (!templateColumns) {
          return false;
        }

        if (targetNodeKey) {
          const targetNode = $getNodeByKey(targetNodeKey);
          if (!$isElementNode(targetNode)) {
            return false;
          }

          applyLayoutPreset(targetNode, templateColumns);
          return true;
        }

        const selection = $getSelection();
        if (!$isRangeSelection(selection)) {
          return false;
        }

        const targetElement = selection.anchor
          .getNode()
          .getTopLevelElementOrThrow();
        applyLayoutPreset(targetElement, templateColumns);
        return true;
      },
      COMMAND_PRIORITY_EDITOR
    );
  }, [editor]);

  // Incomplete payloads (no template) mean "open the preset picker".
  useEffect(() => {
    return editor.registerCommand(
      INSERT_LAYOUT_COMMAND,
      (payload) => {
        if (payload.templateColumns) {
          return false;
        }

        let targetNodeKey: string | null = payload.targetNodeKey ?? null;

        if (!targetNodeKey) {
          editor.getEditorState().read(() => {
            const selection = $getSelection();
            if (!$isRangeSelection(selection)) {
              return;
            }
            const node = selection.anchor.getNode();
            if ($isTextNode(node)) {
              targetNodeKey = node.getTopLevelElementOrThrow().getKey();
            }
          });
        }

        setDialogState({
          ...EMPTY_DIALOG_STATE,
          open: true,
          pendingTargetKey: targetNodeKey,
        });
        return true;
      },
      COMMAND_PRIORITY_HIGH
    );
  }, [editor]);

  const closeDialog = () => {
    setDialogState(EMPTY_DIALOG_STATE);
  };

  const handleSelectPreset = (templateColumns: string) => {
    editor.dispatchCommand(INSERT_LAYOUT_COMMAND, {
      targetNodeKey: dialogState.pendingTargetKey ?? undefined,
      templateColumns,
    });
    closeDialog();
  };

  return (
    <LayoutPresetDialog
      onCancel={closeDialog}
      onOpenChange={(open) => {
        if (!open) {
          closeDialog();
        }
      }}
      onSelectPreset={handleSelectPreset}
      open={dialogState.open}
    />
  );
}

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { LAYOUT_PRESETS } from "./constants";

const TEMPLATE_COLUMN_SEPARATOR = /\s+/;

const getLayoutPreviewColumns = (templateColumns: string) => {
  return templateColumns.split(TEMPLATE_COLUMN_SEPARATOR).filter(Boolean);
};

function LayoutPresetPreview({ templateColumns }: { templateColumns: string }) {
  const columns = getLayoutPreviewColumns(templateColumns);
  const columnOccurrences = new Map<string, number>();

  return (
    <div className="grid h-14 w-full gap-2 rounded-xl border border-border/70 bg-muted/40 p-2">
      <div
        className="grid h-full gap-2"
        style={{ gridTemplateColumns: templateColumns }}
      >
        {columns.map((column) => {
          const currentCount = columnOccurrences.get(column) ?? 0;
          columnOccurrences.set(column, currentCount + 1);

          return (
            <div
              className="rounded-md border border-border/70 bg-background/90 shadow-xs"
              key={`${templateColumns}-${column}-${currentCount}`}
            />
          );
        })}
      </div>
    </div>
  );
}

interface LayoutPresetDialogProps {
  onCancel: () => void;
  onOpenChange: (open: boolean) => void;
  onSelectPreset: (templateColumns: string) => void;
  open: boolean;
}

export function LayoutPresetDialog({
  onCancel,
  onOpenChange,
  onSelectPreset,
  open,
}: LayoutPresetDialogProps) {
  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      <DialogContent
        className="max-h-[calc(100vh-2rem)] overflow-hidden p-0 sm:max-w-2xl"
        showCloseButton
      >
        <DialogHeader className="px-5 pt-5 pb-0 sm:px-6 sm:pt-6">
          <DialogTitle>Choose columns layout</DialogTitle>
          <DialogDescription>
            Pick one of the official Lexical-style column presets.
          </DialogDescription>
        </DialogHeader>

        <div className="max-h-[min(70vh,34rem)] overflow-y-auto px-4 pt-2 pb-4 sm:px-6 sm:pb-6">
          <div className="grid gap-3 sm:grid-cols-2">
            {LAYOUT_PRESETS.map((preset) => (
              <Button
                className="h-auto min-h-32 justify-start rounded-2xl border border-border/80 px-4 py-4 text-left hover:bg-muted/60"
                key={preset.value}
                onClick={() => onSelectPreset(preset.value)}
                type="button"
                variant="ghost"
              >
                <span className="flex w-full flex-col items-start gap-3">
                  <LayoutPresetPreview templateColumns={preset.value} />
                  <span className="flex flex-col items-start gap-1">
                    <span className="font-medium text-foreground text-sm">
                      {preset.label}
                    </span>
                    <span className="text-muted-foreground text-xs">
                      {preset.description}
                    </span>
                    <span className="font-mono text-[11px] text-muted-foreground/80">
                      {preset.value}
                    </span>
                  </span>
                </span>
              </Button>
            ))}
          </div>
        </div>

        <DialogFooter
          className="mt-0 px-4 py-3 sm:px-6"
          showCloseButton={false}
        >
          <Button onClick={onCancel} type="button" variant="outline">
            Cancel
          </Button>
          <Button
            onClick={() =>
              onSelectPreset(LAYOUT_PRESETS[0]?.value ?? "1fr 1fr")
            }
            type="button"
          >
            Use default
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { $createParagraphNode, type ElementNode } from "lexical";
import { $createLayoutContainerNode } from "../../core/nodes/layout/container-node";
import { $createLayoutItemNode } from "../../core/nodes/layout/item-node";

const TEMPLATE_COLUMN_SEPARATOR = /\s+/;

const getColumnCount = (templateColumns: string) => {
  return templateColumns.split(TEMPLATE_COLUMN_SEPARATOR).filter(Boolean)
    .length;
};

export const applyLayoutPreset = (
  targetElement: ElementNode,
  templateColumns: string
) => {
  const layoutContainer = $createLayoutContainerNode(templateColumns);
  const columnCount = getColumnCount(templateColumns);
  let firstParagraph: ReturnType<typeof $createParagraphNode> | null = null;

  for (let index = 0; index < columnCount; index += 1) {
    const layoutItem = $createLayoutItemNode();
    const paragraph = $createParagraphNode();

    if (firstParagraph === null) {
      firstParagraph = paragraph;
    }

    layoutItem.append(paragraph);
    layoutContainer.append(layoutItem);
  }

  targetElement.replace(layoutContainer);
  firstParagraph?.selectEnd();
};
